using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.API.Data; using RaceDay.API.DTOs; using RaceDay.API.Models;
namespace RaceDay.API.Controllers;
[ApiController,Route("api/enrolments")]
public class EnrolmentsController(RaceDayContext db):ControllerBase
{
 [HttpPost] public async Task<IActionResult> Enrol(EnrolmentRequest r){var uid=HttpContext.Session.GetInt32("UserId");if(uid is null)return Unauthorized();if(HttpContext.Session.GetString("Role")!="Participant")return Forbid();var c=await db.Categories.Include(x=>x.Event).SingleOrDefaultAsync(x=>x.Id==r.CategoryId);if(c is null)return NotFound(new{message="Category not found."});if(c.Event!.Date<DateTime.UtcNow)return BadRequest(new{message="Cannot enrol in a past event."});if(await db.Enrolments.AnyAsync(x=>x.ParticipantId==uid&&x.CategoryId==r.CategoryId))return Conflict(new{message="Already enrolled in this category."});var en=new Enrolment{ParticipantId=uid.Value,CategoryId=r.CategoryId};db.Enrolments.Add(en);await db.SaveChangesAsync();return Created($"/api/enrolments/my",new{en.Id,en.ParticipantId,en.CategoryId,en.EnrolmentDate});}
 [HttpGet("my")] public async Task<IActionResult> Mine(){var uid=HttpContext.Session.GetInt32("UserId");if(uid is null)return Unauthorized();if(HttpContext.Session.GetString("Role")!="Participant")return Forbid();return Ok(await db.Enrolments.Include(x=>x.Category).ThenInclude(x=>x!.Event).Include(x=>x.Result).Where(x=>x.ParticipantId==uid).ToListAsync());}
 [HttpGet("event/{eventId:int}")] public async Task<IActionResult> ForEvent(int eventId){var uid=HttpContext.Session.GetInt32("UserId");if(uid is null)return Unauthorized();if(HttpContext.Session.GetString("Role")!="Organiser")return Forbid();var e=await db.Events.FindAsync(eventId);if(e is null)return NotFound();if(e.OrganiserId!=uid)return Forbid();return Ok(await db.Enrolments.Include(x=>x.Participant).Include(x=>x.Category).Where(x=>x.Category!.EventId==eventId).ToListAsync());}
}
